head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/protected_dep_cal.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF40004.xml";
scwin.notiId;
scwin.vSecugrpID = "";
scwin.vBzProcsNo, scwin.vPrtDepoId, scwin.vExerSeq, scwin.visGongsi = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    var url = "/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readStockOptionDutyHold&inputMessageId=STOCKOPTION_DUTYHOLD_LIST_INOUT&outputMessageId=STOCKOPTION_DUTYHOLD_LIST_INOUT";
    url += "&PRTDEPO_ID=" + scwin.vPrtDepoId;
    url += "&STKOPT_DUTY_EXER_SEQ=" + scwin.vExerSeq;
    dts_readStkDutyHold.DataID = encodeURI(url);
    dts_readStkDutyHold.reset();
};
scwin.checkValid = function() {
    if (scwin.visGongsi == true) {
        if (med_STKOPT_DUTY_EXER_PAY_DD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "납입일"));
            med_STKOPT_DUTY_EXER_PAY_DD.focus();
            return false;
        }
        if (med_STKOPT_DUTY_EXER_SHRS.getValue() == "" || med_STKOPT_DUTY_EXER_SHRS.getValue() <= 0) {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "행사 주식수"));
            med_STKOPT_DUTY_EXER_SHRS.focus();
            return false;
        }
    } else {
        if (txb_com_nm.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사명"));
            return false;
        }
        if (txb_nm.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "대상자"));
            txb_nm.focus();
            return false;
        }
        if (txb_RESDBZ_REG_NO.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "생년월일/사업자번호"));
            txb_RESDBZ_REG_NO.focus();
            return false;
        }
        if (cmb_PrtdepoPrnTpCd.BindColVal == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "대상자구분"));
            cmb_PrtdepoPrnTpCd.focus();
            return false;
        }
        if (cmb_PrtdepoObjKindCd.BindColVal == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "주식의 종류"));
            cmb_PrtdepoObjKindCd.focus();
            return false;
        }
        if (med_STKOPT_DUTY_TOT_GRNT_SHRS.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "총 부여 주식수"));
            med_STKOPT_DUTY_TOT_GRNT_SHRS.focus();
            return false;
        }
        if (med_STKOPT_DUTY_RESOL_DD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "부여결의일"));
            med_STKOPT_DUTY_RESOL_DD.focus();
            return false;
        }
        if (med_STKOPT_DUTY_EXER_STRT_DD.getValue() == "" || med_STKOPT_DUTY_EXER_END_DD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "행사기간 시작일/만료일"));
            med_STKOPT_DUTY_EXER_STRT_DD.focus();
            return false;
        }
        if (med_PRTDEPO_END_DD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유기간 만료일"));
            med_PRTDEPO_END_DD.focus();
            return false;
        }
        if (med_PRTDEPO_END_DD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "의무보유기간 만료일"));
            med_PRTDEPO_END_DD.focus();
            return false;
        }
        if (scwin.dateCheck() == false) {
            return false;
        }
    }
    return true;
};
scwin.fn_update = function(isGongsi) {
    var chkValid = scwin.checkValid();
    if (chkValid) {
        dts_readStkDutyHold.setCellData(dts_readStkDutyHold.getRowPosition(), "PRTDEPO_PRN_TP_CD", cmb_PrtdepoPrnTpCd.BindColVal);
        dts_readStkDutyHold.setCellData(dts_readStkDutyHold.getRowPosition(), "PRTDEPO_OBJ_KIND_CD", cmb_PrtdepoObjKindCd.BindColVal);
        var rtn;
        if (isGongsi) {
            rtn = confirm('주식매수선택권 의무보유 납입일, 행사 주식수 수정 하시겠습니까?');
        } else {
            rtn = confirm('주식매수선택권 의무보유 상세내역을 수정 하시겠습니까?');
        }
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            trs_Update.Action = $c.lc.fn_encodeNSession("/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=updateStockOptionDutyHold");
            trs_Update.KeyValue = "JSP(I:pInput=dts_readStkDutyHold)";
            if (isGongsi) {
                trs_Update.Parameters = "EXER=" + "TRUE";
            }
            trs_Update.Post();
        }
    }
};
scwin.fn_save = function() {
    var chkValid = scwin.checkValid();
    if (chkValid) {
        dts_saveStkDutyHold.setCellData(dts_saveStkDutyHold.getRowPosition(), "PRTDEPO_PRN_TP_CD", cmb_PrtdepoPrnTpCd.BindColVal);
        dts_saveStkDutyHold.setCellData(dts_saveStkDutyHold.getRowPosition(), "PRTDEPO_OBJ_KIND_CD", cmb_PrtdepoObjKindCd.BindColVal);
        var rtn = confirm('신규 주식매수선택권 의무보유 내용을 등록 하시겠습니까?');
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            trs_Save.Action = $c.lc.fn_encodeNSession("/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=createStockOptionDutyHold");
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_saveStkDutyHold)";
            trs_Save.Parameters = "TRS_IDX=" + "I";
            trs_Save.Post();
        }
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('주식매수선택권 의무보유 상세내역을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_deleteStkDutyHold.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_deleteStkDutyHold.insertRow();
        dts_deleteStkDutyHold.setCellData(1, "PRTDEPO_ID", dts_readStkDutyHold.getCellData(dts_readStkDutyHold.getRowPosition(), "PRTDEPO_ID"));
        dts_deleteStkDutyHold.setCellData(1, "BZ_PROCS_NO", dts_readStkDutyHold.getCellData(dts_readStkDutyHold.getRowPosition(), "BZ_PROCS_NO"));
        dts_deleteStkDutyHold.setCellData(1, "ISUR_CD", dts_readStkDutyHold.getCellData(dts_readStkDutyHold.getRowPosition(), "ISUR_CD"));
        trs_Delete.Action = $c.lc.fn_encodeNSession("/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=deleteStockOptionDutyHold");
        trs_Delete.KeyValue = "JSP(I:pInput=dts_deleteStkDutyHold)";
        trs_Delete.Post();
    }
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_isur_cd.setValue(arrPar[0].ISUR_CD);
    txb_com_nm.setValue(arrPar[0].COM_NM);
};
scwin.dateCheck = function() {
    if (parseInt(med_STKOPT_DUTY_EXER_STRT_DD.getValue(), '10') > parseInt(med_STKOPT_DUTY_EXER_END_DD.getValue(), '10')) {
        $c.win.alert("[행사기간간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        med_STKOPT_DUTY_EXER_STRT_DD.focus();
        return false;
    }
};
scwin.reloadParent = function() {
    var isChk = $c.frame.path("../").checkIsurCd();
    if (isChk == true) {
        $c.frame.path("../").fn_list_sync();
    }
};
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "STKOPT_DUTY_HD_INPUT_TP_CD",
        cnm: "cmb_STKOPT_DUTY_HD_INPUT_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='STKOPT_DUTY_HD_INPUT_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    strCbd = "";
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "주식매수선택권 의무보유등록"));
    scwin.reloadParent();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "주식매수선택권 의무보유등록"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "주식매수선택권 의무보유수정"));
    scwin.reloadParent();
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "주식매수선택권 의무보유수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "주식매수선택권 의무보유삭제"));
    scwin.reloadParent();
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "주식매수선택권 의무보유삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.btn_SCal_onclick = function() {
    popUpCalendar(med_STKOPT_DUTY_EXER_STRT_DD, 'med_STKOPT_DUTY_EXER_STRT_DD', 'yyyymmdd');
};
scwin.btn_ECal_onclick = function() {
    popUpCalendar(med_STKOPT_DUTY_EXER_END_DD, 'med_STKOPT_DUTY_EXER_END_DD', 'yyyymmdd');
};
scwin.btn_SCalMisc_onclick = function() {
    popUpCalendar(med_PRTDEPO_END_DD, 'med_PRTDEPO_END_DD', 'yyyymmdd');
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_readStkDutyHold_OnLoadCompleted = function(rowcount) {
    // dataset의 처리부분.  combo을 설정하는 부분은 bind을 이용할 수 없다. 나머지는 bind로 처리
    cmb_PrtdepoObjKindCd.setSelectedIndex(cmb_PrtdepoObjKindCd.indexOfColumn("code", dts_readStkDutyHold.getCellData(1, "PRTDEPO_OBJ_KIND_CD"))); // 보호예수대상종류코드
    $c.pdc.fn_setCodCtr(cmb_PrtdepoObjKindCd);
    cmb_PrtdepoPrnTpCd.setSelectedIndex(cmb_PrtdepoPrnTpCd.indexOfColumn("code", dts_readStkDutyHold.getCellData(1, "PRTDEPO_PRN_TP_CD"))); // 보호예수대상구분코드
    $c.pdc.fn_setCodCtr(cmb_PrtdepoPrnTpCd);
    $c.stf.setObjectValue(cmb_STKOPT_DUTY_HD_INPUT_TP_CD, dts_readStkDutyHold.getCellData(1, "STKOPT_DUTY_HD_INPUT_TP_CD"));
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.vPrtDepoId = $c.frame.path("../").selPrtDepoId;
    scwin.vExerSeq = $c.frame.path("../").selExerSeq;
    scwin.visGongsi = $c.frame.path("../").isGongsi;
    $c.pdc.fn_filCodCtr(cmb_PrtdepoPrnTpCd, codArrAtrTyp, undefined); // 보호예수대상자구분코드
    $c.pdc.fn_filCodCtr(cmb_PrtdepoObjKindCd, codArrObjKnd, undefined); // 보호예수대상종류코드
    $c.elw.fn_searchCode();
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    $c.stf.showObj(image_2, false);
    if (js_dep_cd != 'ZSYS') {
        $c.stf.showObj(btn_Save);
        $c.stf.showObj(btn_Update);
        $c.stf.showObj(btn_Delete);
    }
    if (scwin.vPrtDepoId == "") {
        buttonSet.setInsertStatus();
        dts_saveStkDutyHold.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=STOCKOPTION_DUTYHOLD_LIST_INOUT";
        dts_saveStkDutyHold.Reset();
        dts_saveStkDutyHold.insertRow();
    } else {
        scwin.fn_read();
        buttonSet.setUpdateStatus();
    }
    if (js_belngdepcd == "2600" || js_belngdepcd == "3400" || scwin.visGongsi == true) {
        //공시부는 납입일, 행사주식수만 수정가능
        $c.stf.showObj(img_COM_NM, false);
        $c.stf.showObj(image_1, false);
        $c.stf.showObj(btn_SCal, false);
        $c.stf.showObj(btn_ECal, false);
        $c.stf.showObj(btn_SCalMisc, false);
        txb_nm.setReadOnly(true);
        txb_nm.style.backgroundColor = "#b9d4f7";
        txb_RESDBZ_REG_NO.setReadOnly(true);
        txb_RESDBZ_REG_NO.style.backgroundColor = "#b9d4f7";
        cmb_PrtdepoPrnTpCd.setDisabled(true);
        cmb_PrtdepoObjKindCd.setDisabled(true);
        cmb_STKOPT_DUTY_HD_INPUT_TP_CD.setDisabled(true);
        med_STKOPT_DUTY_TOT_GRNT_SHRS.setDisabled(true);
        med_STKOPT_DUTY_RESOL_DD.setDisabled(true);
        med_STKOPT_DUTY_EXER_STRT_DD.setDisabled(true);
        med_STKOPT_DUTY_EXER_END_DD.setDisabled(true);
        med_PRTDEPO_END_DD.setDisabled(true);
        $c.stf.showObj(image_2, true);
        med_STKOPT_DUTY_EXER_PAY_DD.setReadOnly(false);
        med_STKOPT_DUTY_EXER_SHRS.setReadOnly(false);
        btn_Delete.setDisabled(true);
        btn_Delete.src = "../img/btn_delete_d.gif";
        //btn_Save.disabled = true;
        //btn_Save.src = "../img/btn_input_d.gif";

    }
};
scwin.btn_Update_onclick = function() {
    if (js_belngdepcd == "2600" || js_belngdepcd == "3400" || scwin.visGongsi == true) {
        scwin.fn_update(scwin.visGongsi);
    } else {
        scwin.fn_update(false);
    }
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_save();
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_nm);
};
scwin.image_1_onclick = function() {
    popUpCalendar(med_STKOPT_DUTY_RESOL_DD, 'med_STKOPT_DUTY_RESOL_DD', 'yyyymmdd');
};
scwin.image_2_onclick = function() {
    popUpCalendar(med_STKOPT_DUTY_EXER_PAY_DD, 'med_STKOPT_DUTY_EXER_PAY_DD', 'yyyymmdd');
};
